CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('PLAYER','ORGANIZER','ADMIN') NOT NULL DEFAULT 'PLAYER', enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE player_profiles (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, username VARCHAR(50) NOT NULL UNIQUE, profile_image VARCHAR(500), favorite_game VARCHAR(100), skill_level VARCHAR(50), total_matches INT NOT NULL DEFAULT 0, wins INT NOT NULL DEFAULT 0, losses INT NOT NULL DEFAULT 0, ranking_points INT NOT NULL DEFAULT 0, CONSTRAINT fk_profile_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE tournaments (id BIGINT AUTO_INCREMENT PRIMARY KEY, organizer_id BIGINT NOT NULL, name VARCHAR(150) NOT NULL, game_name VARCHAR(100) NOT NULL, description TEXT, format VARCHAR(50) NOT NULL, entry_fee DECIMAL(12,2) NOT NULL DEFAULT 0, max_players INT NOT NULL, start_date TIMESTAMP NOT NULL, status ENUM('PENDING','UPCOMING','ONGOING','COMPLETED','CANCELLED') NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT chk_max_players CHECK (max_players > 1), CONSTRAINT fk_tournament_organizer FOREIGN KEY (organizer_id) REFERENCES users(id));
CREATE TABLE registrations (id BIGINT AUTO_INCREMENT PRIMARY KEY, player_id BIGINT NOT NULL, tournament_id BIGINT NOT NULL, registration_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, status ENUM('REGISTERED','CANCELLED') NOT NULL DEFAULT 'REGISTERED', UNIQUE(player_id, tournament_id), CONSTRAINT fk_registration_player FOREIGN KEY (player_id) REFERENCES player_profiles(id), CONSTRAINT fk_registration_tournament FOREIGN KEY (tournament_id) REFERENCES tournaments(id) ON DELETE CASCADE);
CREATE TABLE matches (id BIGINT AUTO_INCREMENT PRIMARY KEY, tournament_id BIGINT NOT NULL, player_one_id BIGINT NOT NULL, player_two_id BIGINT NOT NULL, winner_id BIGINT, round_name VARCHAR(100) NOT NULL, status ENUM('SCHEDULED','COMPLETED') NOT NULL DEFAULT 'SCHEDULED', CONSTRAINT fk_match_tournament FOREIGN KEY (tournament_id) REFERENCES tournaments(id) ON DELETE CASCADE, CONSTRAINT fk_match_one FOREIGN KEY (player_one_id) REFERENCES player_profiles(id), CONSTRAINT fk_match_two FOREIGN KEY (player_two_id) REFERENCES player_profiles(id), CONSTRAINT fk_match_winner FOREIGN KEY (winner_id) REFERENCES player_profiles(id));
CREATE TABLE rankings (id BIGINT AUTO_INCREMENT PRIMARY KEY, player_id BIGINT NOT NULL UNIQUE, points INT NOT NULL DEFAULT 0, wins INT NOT NULL DEFAULT 0, losses INT NOT NULL DEFAULT 0, CONSTRAINT fk_ranking_player FOREIGN KEY (player_id) REFERENCES player_profiles(id) ON DELETE CASCADE);
CREATE TABLE rewards (id BIGINT AUTO_INCREMENT PRIMARY KEY, player_id BIGINT NOT NULL, reward_type VARCHAR(100) NOT NULL, amount INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_reward_player FOREIGN KEY (player_id) REFERENCES player_profiles(id) ON DELETE CASCADE);
CREATE TABLE reports (id BIGINT AUTO_INCREMENT PRIMARY KEY, reported_user BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, status ENUM('OPEN','RESOLVED','DISMISSED') NOT NULL DEFAULT 'OPEN', CONSTRAINT fk_report_user FOREIGN KEY (reported_user) REFERENCES users(id));
CREATE INDEX idx_tournaments_game ON tournaments(game_name); CREATE INDEX idx_matches_tournament ON matches(tournament_id);
